CREATE TABLE kids_parent_activities (
 owner_user_id TEXT NOT NULL, workspace_id TEXT NOT NULL, id TEXT NOT NULL,
 revision INTEGER NOT NULL CHECK(revision>=1), created_at TEXT NOT NULL, last_parent_operation_id TEXT NOT NULL,
 PRIMARY KEY(owner_user_id,workspace_id,id), FOREIGN KEY(owner_user_id,workspace_id) REFERENCES kids_state(user_id,id) ON DELETE CASCADE
);
--> statement-breakpoint
CREATE TABLE kids_parent_activity_versions (
 owner_user_id TEXT NOT NULL, workspace_id TEXT NOT NULL, activity_id TEXT NOT NULL,
 revision INTEGER NOT NULL CHECK(revision>=1), effective_from TEXT NOT NULL,
 definition TEXT CHECK(definition IS NULL OR json_valid(definition)), last_parent_operation_id TEXT NOT NULL,
 PRIMARY KEY(owner_user_id,workspace_id,activity_id,revision), FOREIGN KEY(owner_user_id,workspace_id,activity_id) REFERENCES kids_parent_activities(owner_user_id,workspace_id,id) ON DELETE CASCADE
);
--> statement-breakpoint
CREATE TABLE kids_parent_activity_occurrences (
 owner_user_id TEXT NOT NULL, workspace_id TEXT NOT NULL, activity_id TEXT NOT NULL, day TEXT NOT NULL, child_id TEXT NOT NULL,
 revision INTEGER NOT NULL CHECK(revision>=1), definition_revision INTEGER NOT NULL, value TEXT NOT NULL CHECK(json_valid(value)), last_parent_operation_id TEXT NOT NULL,
 PRIMARY KEY(owner_user_id,workspace_id,activity_id,day,child_id), FOREIGN KEY(owner_user_id,workspace_id,activity_id,definition_revision) REFERENCES kids_parent_activity_versions(owner_user_id,workspace_id,activity_id,revision) ON DELETE CASCADE
);
--> statement-breakpoint
CREATE TRIGGER kids_parent_activity_insert_guard BEFORE INSERT ON kids_parent_activities WHEN NEW.revision<>1 OR NOT EXISTS(SELECT 1 FROM kids_operation_receipts r JOIN kids_state k ON k.user_id=r.owner_user_id AND k.id=r.workspace_id WHERE r.owner_user_id=NEW.owner_user_id AND r.workspace_id=NEW.workspace_id AND r.operation_id=NEW.last_parent_operation_id AND r.committed_revision=k.revision AND CASE WHEN json_valid(r.source_authority) THEN json_extract(r.source_authority,'$.kind')='parent-activity-v1' AND json_extract(r.source_authority,'$.result.activityId')=NEW.id AND json_extract(r.source_authority,'$.result.activityRevision')=NEW.revision AND json_extract(r.source_authority,'$.result.createdAt')=NEW.created_at AND json_extract(r.source_authority,'$.result.action')='add' ELSE 0 END) BEGIN SELECT RAISE(ABORT,'KIDS_PARENT_ACTIVITY_RECEIPT_REQUIRED'); END;
--> statement-breakpoint
CREATE TRIGGER kids_parent_activity_update_guard BEFORE UPDATE ON kids_parent_activities WHEN NEW.revision<>OLD.revision+1 OR NOT EXISTS(SELECT 1 FROM kids_operation_receipts r JOIN kids_state k ON k.user_id=r.owner_user_id AND k.id=r.workspace_id WHERE r.owner_user_id=NEW.owner_user_id AND r.workspace_id=NEW.workspace_id AND r.operation_id=NEW.last_parent_operation_id AND r.committed_revision=k.revision AND CASE WHEN json_valid(r.source_authority) THEN json_extract(r.source_authority,'$.kind')='parent-activity-v1' AND json_extract(r.source_authority,'$.result.activityId')=NEW.id AND json_extract(r.source_authority,'$.result.activityRevision')=NEW.revision AND json_extract(r.source_authority,'$.result.createdAt')=NEW.created_at AND json_extract(r.source_authority,'$.result.action') IN ('edit','end') ELSE 0 END) BEGIN SELECT RAISE(ABORT,'KIDS_PARENT_ACTIVITY_RECEIPT_REQUIRED'); END;
--> statement-breakpoint
CREATE TRIGGER kids_parent_version_insert_guard BEFORE INSERT ON kids_parent_activity_versions WHEN NOT EXISTS(SELECT 1 FROM kids_operation_receipts r JOIN kids_state k ON k.user_id=r.owner_user_id AND k.id=r.workspace_id WHERE r.owner_user_id=NEW.owner_user_id AND r.workspace_id=NEW.workspace_id AND r.operation_id=NEW.last_parent_operation_id AND r.committed_revision=k.revision AND CASE WHEN json_valid(r.source_authority) THEN json_extract(r.source_authority,'$.kind')='parent-activity-v1' AND json_extract(r.source_authority,'$.result.activityId')=NEW.activity_id AND json_extract(r.source_authority,'$.result.version.revision')=NEW.revision AND json_extract(r.source_authority,'$.result.version.effectiveFrom')=NEW.effective_from AND json_extract(r.source_authority,'$.result.version.definition') IS NEW.definition AND EXISTS(SELECT 1 FROM kids_parent_activities a WHERE a.owner_user_id=NEW.owner_user_id AND a.workspace_id=NEW.workspace_id AND a.id=NEW.activity_id AND a.revision=NEW.revision AND a.last_parent_operation_id=NEW.last_parent_operation_id) ELSE 0 END) BEGIN SELECT RAISE(ABORT,'KIDS_PARENT_VERSION_RECEIPT_REQUIRED'); END;
--> statement-breakpoint
CREATE TRIGGER kids_parent_version_update_guard BEFORE UPDATE ON kids_parent_activity_versions BEGIN SELECT RAISE(ABORT,'KIDS_PARENT_VERSION_IMMUTABLE'); END;
--> statement-breakpoint
CREATE TRIGGER kids_parent_occurrence_insert_guard BEFORE INSERT ON kids_parent_activity_occurrences WHEN NEW.revision<>(SELECT COALESCE(MAX(revision),0)+1 FROM kids_parent_activity_occurrences WHERE owner_user_id=NEW.owner_user_id AND workspace_id=NEW.workspace_id AND activity_id=NEW.activity_id AND day=NEW.day AND child_id=NEW.child_id) OR NOT EXISTS(SELECT 1 FROM kids_operation_receipts r JOIN kids_state k ON k.user_id=r.owner_user_id AND k.id=r.workspace_id WHERE r.owner_user_id=NEW.owner_user_id AND r.workspace_id=NEW.workspace_id AND r.operation_id=NEW.last_parent_operation_id AND r.committed_revision=k.revision AND CASE WHEN json_valid(r.source_authority) THEN json_extract(r.source_authority,'$.kind')='parent-activity-v1' AND json_extract(r.source_authority,'$.result.action')='session' AND json_extract(r.source_authority,'$.result.activityId')=NEW.activity_id AND json_extract(r.source_authority,'$.result.occurrence.day')=NEW.day AND json_extract(r.source_authority,'$.result.occurrence.childId')=NEW.child_id AND json_extract(r.source_authority,'$.result.occurrence.revision')=NEW.revision AND json_extract(r.source_authority,'$.result.occurrence.definitionRevision')=NEW.definition_revision AND json_extract(r.source_authority,'$.result.occurrence.definition')=json_extract(NEW.value,'$.definition') AND json_extract(r.source_authority,'$.result.occurrence.completed')=json_extract(NEW.value,'$.completed') AND json_extract(r.source_authority,'$.result.occurrence.pinned')=json_extract(NEW.value,'$.pinned') AND json_extract(r.source_authority,'$.result.occurrence.travel')=json_extract(NEW.value,'$.travel') AND EXISTS(SELECT 1 FROM kids_parent_activity_versions v WHERE v.owner_user_id=NEW.owner_user_id AND v.workspace_id=NEW.workspace_id AND v.activity_id=NEW.activity_id AND v.revision=NEW.definition_revision AND v.definition=json_extract(NEW.value,'$.definition') AND json_extract(v.definition,'$.childId')=NEW.child_id) ELSE 0 END) BEGIN SELECT RAISE(ABORT,'KIDS_PARENT_OCCURRENCE_RECEIPT_REQUIRED'); END;
--> statement-breakpoint
CREATE TRIGGER kids_parent_occurrence_update_guard BEFORE UPDATE ON kids_parent_activity_occurrences WHEN NEW.revision<>OLD.revision+1 OR (json_extract(OLD.value,'$.pinned')=1 AND (json_extract(NEW.value,'$.pinned')<>1 OR NEW.definition_revision<>OLD.definition_revision OR json_extract(NEW.value,'$.definition')<>json_extract(OLD.value,'$.definition'))) OR NOT EXISTS(SELECT 1 FROM kids_operation_receipts r JOIN kids_state k ON k.user_id=r.owner_user_id AND k.id=r.workspace_id WHERE r.owner_user_id=NEW.owner_user_id AND r.workspace_id=NEW.workspace_id AND r.operation_id=NEW.last_parent_operation_id AND r.committed_revision=k.revision AND CASE WHEN json_valid(r.source_authority) THEN json_extract(r.source_authority,'$.kind')='parent-activity-v1' AND json_extract(r.source_authority,'$.result.action')='session' AND json_extract(r.source_authority,'$.result.activityId')=NEW.activity_id AND json_extract(r.source_authority,'$.result.occurrence.day')=NEW.day AND json_extract(r.source_authority,'$.result.occurrence.childId')=NEW.child_id AND json_extract(r.source_authority,'$.result.occurrence.revision')=NEW.revision AND json_extract(r.source_authority,'$.result.occurrence.definitionRevision')=NEW.definition_revision AND json_extract(r.source_authority,'$.result.occurrence.definition')=json_extract(NEW.value,'$.definition') AND json_extract(r.source_authority,'$.result.occurrence.completed')=json_extract(NEW.value,'$.completed') AND json_extract(r.source_authority,'$.result.occurrence.pinned')=json_extract(NEW.value,'$.pinned') AND json_extract(r.source_authority,'$.result.occurrence.travel')=json_extract(NEW.value,'$.travel') AND EXISTS(SELECT 1 FROM kids_parent_activity_versions v WHERE v.owner_user_id=NEW.owner_user_id AND v.workspace_id=NEW.workspace_id AND v.activity_id=NEW.activity_id AND v.revision=NEW.definition_revision AND v.definition=json_extract(NEW.value,'$.definition') AND json_extract(v.definition,'$.childId')=NEW.child_id) ELSE 0 END) BEGIN SELECT RAISE(ABORT,'KIDS_PARENT_OCCURRENCE_RECEIPT_REQUIRED'); END;
