CREATE TRIGGER kids_parent_activities_identity_guard BEFORE UPDATE ON kids_parent_activities WHEN OLD.owner_user_id<>NEW.owner_user_id OR OLD.workspace_id<>NEW.workspace_id OR OLD.id<>NEW.id OR OLD.created_at<>NEW.created_at BEGIN SELECT RAISE(ABORT,'KIDS_PARENT_IDENTITY_IMMUTABLE'); END;
--> statement-breakpoint
CREATE TRIGGER kids_parent_activity_occurrences_identity_guard BEFORE UPDATE ON kids_parent_activity_occurrences WHEN OLD.owner_user_id<>NEW.owner_user_id OR OLD.workspace_id<>NEW.workspace_id OR OLD.activity_id<>NEW.activity_id OR OLD.day<>NEW.day OR OLD.child_id<>NEW.child_id BEGIN SELECT RAISE(ABORT,'KIDS_PARENT_IDENTITY_IMMUTABLE'); END;
