CREATE TRIGGER kids_parent_activities_delete_guard BEFORE DELETE ON kids_parent_activities WHEN EXISTS(SELECT 1 FROM kids_state WHERE user_id=OLD.owner_user_id AND id=OLD.workspace_id) BEGIN SELECT RAISE(ABORT,'KIDS_PARENT_HISTORY_PRESERVED'); END;
--> statement-breakpoint
CREATE TRIGGER kids_parent_activity_versions_delete_guard BEFORE DELETE ON kids_parent_activity_versions WHEN EXISTS(SELECT 1 FROM kids_state WHERE user_id=OLD.owner_user_id AND id=OLD.workspace_id) BEGIN SELECT RAISE(ABORT,'KIDS_PARENT_HISTORY_PRESERVED'); END;
--> statement-breakpoint
CREATE TRIGGER kids_parent_activity_occurrences_delete_guard BEFORE DELETE ON kids_parent_activity_occurrences WHEN EXISTS(SELECT 1 FROM kids_state WHERE user_id=OLD.owner_user_id AND id=OLD.workspace_id) BEGIN SELECT RAISE(ABORT,'KIDS_PARENT_HISTORY_PRESERVED'); END;
--> statement-breakpoint
CREATE TRIGGER kids_parent_receipt_delete_guard BEFORE DELETE ON kids_operation_receipts WHEN EXISTS(SELECT 1 FROM kids_state WHERE user_id=OLD.owner_user_id AND id=OLD.workspace_id) AND CASE WHEN json_valid(OLD.source_authority) THEN json_extract(OLD.source_authority,'$.kind')='parent-activity-v1' ELSE 0 END BEGIN SELECT RAISE(ABORT,'KIDS_PARENT_RECEIPT_IMMUTABLE'); END;
